<?php require_once 'auth.php'; requireAdmin();
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT * FROM users WHERE id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){header('Location: users.php');exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=trim($_POST['email']);$role=$_POST['role'];if(!in_array($role,['Admin','Editor'])){$role='Editor';}
try{if(!empty($_POST['password'])){$hash=password_hash($_POST['password'],PASSWORD_DEFAULT);$stmt=$pdo->prepare('UPDATE users SET name=?,email=?,password=?,role=? WHERE id=?');$stmt->execute([$name,$email,$hash,$role,$id]);}else{$stmt=$pdo->prepare('UPDATE users SET name=?,email=?,role=? WHERE id=?');$stmt->execute([$name,$email,$role,$id]);}if($id==$_SESSION['user_id']){$_SESSION['name']=$name;$_SESSION['role']=$role;}header('Location: users.php');exit;}catch(PDOException $e){$error='حدث خطأ أو الإيميل مستخدم مسبقاً';}}
require_once 'header.php'; ?>
<div class="admin-layout"><?php require_once 'sidebar.php'; ?><main class="admin-content"><h1>تعديل مستخدم</h1><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="POST" class="card"><input class="form-control" name="name" value="<?= e($item['name']) ?>" required><input class="form-control" type="email" name="email" value="<?= e($item['email']) ?>" required><input class="form-control" type="password" name="password" placeholder="كلمة مرور جديدة - اختياري"><select class="form-control" name="role"><option value="Editor" <?= $item['role']==='Editor'?'selected':'' ?>>Editor</option><option value="Admin" <?= $item['role']==='Admin'?'selected':'' ?>>Admin</option></select><button class="btn">تحديث</button></form></main></div></body></html>
